To find papers with tables comparing five or more systems, I'll create a Python script that parses Markdown files for such tables. The script will:
1. Identify Markdown tables (lines starting with `|`)
2. Check if the table has ≥5 data rows after the header
3. Output JSON for `claim` if found

First, I'll save the script using `save_tool`:

```bash
cat > /work/check_tables.py << 'EOF'
import sys
import re

def main():
    filename = sys.argv[1]
    with open(filename, 'r') as f:
        lines = f.readlines()

    in_table = False
    table_lines = []
    for line in lines:
        if line.strip().startswith('|'):
            if not in_table:
                in_table = True
                table_lines = [line]
            else:
                table_lines.append(line)
        else:
            if in_table:
                if len(table_lines) >= 2 and re.match(r'\|.*\|', table_lines[1]):
                    separator = table_lines[1]
                    if re.match(r'\|[-:]*\|', separator):
                        data_rows = 0
                        for i in range(2, len(table_lines)):
                            if table_lines[i].strip() == '':
                                break
                            data_rows += 1
                        if data_rows >= 5:
                            quote = table_lines[0].strip() + " " + table_lines[1].strip()
                            print(f'{{"s": "{filename}", "p": "has_table_with_five_or_more_systems", "o": "true", "file": "{filename}", "quote": "{quote}"}}')
                in_table = False
                table_lines = []

    if in_table:
        if len(table_lines) >= 2 and re.match(r'\|.*\|', table_lines[1]):
            separator = table_lines[1]
            if re.match(r'\|[-:]*\|', separator):
                data_rows = 0
                for i in range(2, len(table_lines)):
                    if table_lines[i].strip() == '':
                        break
                    data_rows += 1
                if data_rows >= 5:
                    quote = table_lines[0].strip() + " " + table_lines[1].strip()
                    print(f'{{"s": "{filename}", "p": "has_table_with_five_or_more_systems", "o": "true", "file": "{filename}", "quote": "{quote}"}}')

if __name__ == '__main__':
    main()
EOF
save_tool /work/check_tables.py
